function makeArray() {
  return { store: new Array(0), length: 0, capacity: 0 };
}

function push(da, value) {
  if (da.length === da.capacity) {
    const bigger = da.capacity === 0 ? 1 : da.capacity * 2;
    const moved = new Array(bigger);
    for (let i = 0; i < da.length; i++) moved[i] = da.store[i];
    da.store = moved;
    da.capacity = bigger;
  }
  da.store[da.length] = value;
  da.length++;
  return da;
}

const da = makeArray();
for (let i = 1; i <= 9; i++) {
  push(da, i);
  console.log("length", da.length, "capacity", da.capacity);
}

