function copiesForDoubling(n) {
  let capacity = 0, length = 0, copies = 0;
  for (let i = 0; i < n; i++) {
    if (length === capacity) {
      capacity = capacity === 0 ? 1 : capacity * 2;
      copies += length;
    }
    length++;
  }
  return copies;
}

function copiesForPlusOne(n) {
  let capacity = 0, length = 0, copies = 0;
  for (let i = 0; i < n; i++) {
    if (length === capacity) {
      capacity = capacity + 1;
      copies += length;
    }
    length++;
  }
  return copies;
}

for (const n of [8, 64, 1024]) {
  console.log(n, "doubling:", copiesForDoubling(n), "  plus-one:", copiesForPlusOne(n));
}

function insertAt(arr, index, value) {
  arr.push(arr[arr.length - 1]);
  for (let i = arr.length - 2; i > index; i--) arr[i] = arr[i - 1];
  arr[index] = value;
  return arr;
}

console.log(insertAt([1, 2, 4, 5], 2, 3));

function removeAll(arr, value) {
  let write = 0;
  for (let read = 0; read < arr.length; read++) {
    if (arr[read] !== value) arr[write++] = arr[read];
  }
  arr.length = write;
  return arr;
}

