function insertAt(arr, index, value) {
  if (index < 0 || index > arr.length) throw new Error("index out of range");
  const out = new Array(arr.length + 1);
  for (let i = 0; i < index; i++) out[i] = arr[i];
  out[index] = value;
  for (let i = index; i < arr.length; i++) out[i + 1] = arr[i];
  return out;
}

