function moveZeroesToEnd(arr) {
  let write = 0;
  for (let read = 0; read < arr.length; read++) {
    if (arr[read] !== 0) {
      arr[write] = arr[read];
      write++;
    }
  }
  while (write < arr.length) {
    arr[write] = 0;
    write++;
  }
  return arr;
}
